-- Where a listing's author suggests meeting (Д2.1): a point picked on the map with its name and address. It belongs to
-- the listing, not to the catalog's venues.
ALTER TABLE "listings" ADD COLUMN "place_name" TEXT,
ADD COLUMN "place_address" TEXT,
ADD COLUMN "place_latitude" DECIMAL(9,6),
ADD COLUMN "place_longitude" DECIMAL(9,6);

ALTER TABLE "listings" ADD CONSTRAINT "listings_place_check" CHECK (
    ("place_name" IS NULL) = ("place_address" IS NULL)
    AND ("place_name" IS NULL) = ("place_latitude" IS NULL)
    AND ("place_name" IS NULL) = ("place_longitude" IS NULL)
);
